# WARNING: Under review - generated by LLM.

"""Course-code guards for the cumulative Week 4 Day 1--2 starter."""

import ast
import sys
from pathlib import Path

import pytest

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT / "src"))

STARTER = ROOT / "src" / "tiny_llm" / "agent"
REFSOL = ROOT / "src" / "tiny_llm_ref" / "agent"
MODULES = ("generation", "loop", "protocol", "workspace")


def _tree(root: Path, module: str) -> ast.Module:
    return ast.parse((root / f"{module}.py").read_text(encoding="utf-8"))


def _public_surface(root: Path, module: str) -> dict[str, tuple]:
    """Return public classes/functions and their exact signatures."""

    surface = {}
    for node in _tree(root, module).body:
        if isinstance(node, ast.ClassDef) and not node.name.startswith("_"):
            methods = tuple(
                (item.name, ast.unparse(item.args), ast.unparse(item.returns))
                for item in node.body
                if isinstance(item, (ast.FunctionDef, ast.AsyncFunctionDef))
                and not item.name.startswith("_")
            )
            surface[node.name] = methods
        elif isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)) and not (
            node.name.startswith("_")
        ):
            surface[node.name] = (ast.unparse(node.args), ast.unparse(node.returns))
    return surface


def _dataclass_fields(root: Path, module: str) -> dict[str, tuple]:
    fields = {}
    for node in _tree(root, module).body:
        if not isinstance(node, ast.ClassDef):
            continue
        if not any(
            isinstance(decorator, ast.Name)
            and decorator.id == "dataclass"
            or isinstance(decorator, ast.Call)
            and isinstance(decorator.func, ast.Name)
            and decorator.func.id == "dataclass"
            for decorator in node.decorator_list
        ):
            continue
        fields[node.name] = tuple(
            (
                item.target.id,
                ast.unparse(item.annotation),
                ast.unparse(item.value) if item.value is not None else "<required>",
            )
            for item in node.body
            if isinstance(item, ast.AnnAssign)
            and isinstance(item.target, ast.Name)
            and not item.target.id.startswith("_")
        )
    return fields


def _public_bodies(root: Path, module: str):
    for node in _tree(root, module).body:
        if isinstance(node, ast.ClassDef) and not node.name.startswith("_"):
            for item in node.body:
                if isinstance(item, (ast.FunctionDef, ast.AsyncFunctionDef)) and not (
                    item.name.startswith("_")
                ):
                    yield f"{node.name}.{item.name}", item.body
        elif isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)) and not (
            node.name.startswith("_")
        ):
            yield node.name, node.body


def _is_stub(body) -> bool:
    return not [
        statement
        for statement in body
        if not isinstance(statement, ast.Pass)
        and not (
            isinstance(statement, ast.Expr)
            and isinstance(statement.value, ast.Constant)
            and isinstance(statement.value.value, str)
        )
    ]


@pytest.mark.parametrize("module", MODULES)
def test_starter_public_contract_matches_reference(module):
    assert _public_surface(STARTER, module) == _public_surface(REFSOL, module)
    assert _dataclass_fields(STARTER, module) == _dataclass_fields(REFSOL, module)


@pytest.mark.parametrize("module", MODULES)
def test_starter_is_solution_free_and_reference_is_implemented(module):
    reference = dict(_public_bodies(REFSOL, module))
    for name, body in _public_bodies(STARTER, module):
        assert _is_stub(body), f"starter {module}.{name} contains solution logic"
        assert name in reference and not _is_stub(reference[name]), (
            f"reference {module}.{name} must implement the starter declaration"
        )


def test_package_exports_match_the_published_day_2_surface():
    import tiny_llm.agent as starter
    import tiny_llm_ref.agent as refsol

    expected = {
        "AgentError",
        "AgentEvent",
        "AgentLimits",
        "AgentRun",
        "FinalAction",
        "ToolAction",
        "ToolPolicy",
        "Workspace",
        "build_system_prompt",
        "generate_response",
        "initial_messages",
        "parse_action",
        "run_agent",
    }
    assert set(starter.__all__) == set(refsol.__all__) == expected


def test_only_day_1_and_day_2_modules_exist_in_the_starter():
    allowed = {"__init__.py", "generation.py", "loop.py", "protocol.py", "workspace.py"}
    assert {path.name for path in STARTER.glob("*.py")} == allowed


def test_day_2_workspace_surface_has_no_effect_api():
    surface = _public_surface(STARTER, "workspace")
    assert set(surface) == {"ToolPolicy", "Workspace"}
    assert {name for name, *_ in surface["Workspace"]} == {
        "available_tools",
        "resolve_path",
        "list_files",
        "read_file",
        "execute",
    }
    source = (STARTER / "workspace.py").read_text(encoding="utf-8")
    for future_name in (
        "EffectReceipt",
        "ReceiptStore",
        "write_file",
        "edit_file",
        "run_command",
    ):
        assert future_name not in source


def test_removed_catalog_hash_is_not_exported_or_declared():
    for root in (STARTER, REFSOL):
        source = (root / "protocol.py").read_text(encoding="utf-8")
        assert "TOOL_CATALOG_HASH" not in source
        assert "tool_catalog_hash" not in source


def test_starter_does_not_import_the_reference_solution():
    for path in STARTER.glob("*.py"):
        source = path.read_text(encoding="utf-8")
        assert "tiny_llm_ref" not in source
